def minimum_pass_cost(size, corridors, start, exit_node):
    unused = []
    used = []
    for node in range(size):
        unused.append(None)
        used.append(None)
    unused[start] = 0
    for iteration in range(2 * size - 1):
        updated = False
        for corridor in corridors:
            a = corridor[0]
            b = corridor[1]
            cost = corridor[2]
            if unused[a] is not None:
                candidate = unused[a] + cost
                if unused[b] is None or candidate < unused[b]:
                    unused[b] = candidate
                    updated = True
                if used[b] is None or unused[a] < used[b]:
                    used[b] = unused[a]
                    updated = True
            if used[a] is not None:
                candidate = used[a] + cost
                if used[b] is None or candidate < used[b]:
                    used[b] = candidate
                    updated = True
        if not updated:
            break
    without = unused[exit_node]
    with_pass = used[exit_node]
    if without is None:
        return -1
    if with_pass is not None and with_pass < without:
        return with_pass
    return without

